package com.snakesteak.collectionlogpopupenhanced.overlay;

import com.snakesteak.collectionlogpopupenhanced.CollectionLogPopupEnhancedConfig;
import com.snakesteak.collectionlogpopupenhanced.rarity.PreviewTier;
import com.snakesteak.collectionlogpopupenhanced.rarity.RarityTier;
import com.snakesteak.collectionlogpopupenhanced.sound.SoundManager;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.List;
import net.runelite.api.Client;
import net.runelite.client.game.ItemManager;
import org.junit.Before;
import org.junit.Test;
import org.mockito.InOrder;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.inOrder;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

/**
 * Covers the "delay CoX popups until chest" queue behaviour. Each item is given a distinct tier so
 * the sound call - which fires once as an item is dequeued - identifies which one is showing;
 * nothing else about the current item is observable from outside.
 */
public class CollectionLogOverlayHoldTest
{
	// FOLD_MILLIS + ICON_POP_MILLIS + FADE_MILLIS, plus a margin. overlayDisplaySeconds is stubbed
	// to 0 below, so this is the whole lifetime of an item on screen.
	private static final long TOTAL_ANIMATION_MILLIS = 550 + 400 + 400 + 150;

	private CollectionLogPopupEnhancedConfig config;
	private SoundManager soundManager;
	private CollectionLogOverlay overlay;

	@Before
	public void before()
	{
		Client client = mock(Client.class);
		ItemManager itemManager = mock(ItemManager.class);
		config = mock(CollectionLogPopupEnhancedConfig.class);
		soundManager = mock(SoundManager.class);

		// Unstubbed these return 0, sending render() down its degenerate-viewport fallback.
		when(client.getViewportXOffset()).thenReturn(4);
		when(client.getViewportWidth()).thenReturn(1272);
		when(client.getRealDimensions()).thenReturn(new Dimension(1280, 720));

		when(config.overlayScalePercent()).thenReturn(100);
		when(config.overlayDisplaySeconds()).thenReturn(0);
		when(config.backgroundDarkness()).thenReturn(50);
		when(config.panelStyle()).thenReturn(PanelStyle.COLORFUL);
		when(config.previewTier()).thenReturn(PreviewTier.NONE);
		when(config.textRenderMode()).thenReturn(TextRenderMode.SMOOTH);
		when(config.leftPanelStat()).thenReturn(LeftPanelStat.KILL_COUNT);
		when(config.rightPanelStat()).thenReturn(RightPanelStat.DROP_RATE);
		when(config.showProgressBar()).thenReturn(true);
		when(config.bulkUnlockSfx()).thenReturn(false);
		when(config.colourStatLabel()).thenReturn(Color.WHITE);
		when(config.colourStatValue()).thenReturn(Color.WHITE);
		when(config.colourCaption()).thenReturn(Color.WHITE);
		when(config.colourCommonTier()).thenReturn(Color.WHITE);
		when(config.colourUncommonTier()).thenReturn(Color.GREEN);
		when(config.colourRareTier()).thenReturn(Color.BLUE);
		when(config.colourVeryRareTier()).thenReturn(Color.MAGENTA);
		when(config.colourPetTier()).thenReturn(Color.YELLOW);

		overlay = new CollectionLogOverlay(client, itemManager, config, soundManager);
	}

	private void enqueue(String name, RarityTier tier, boolean held)
	{
		overlay.enqueue(name, 1, tier, 0, false, null, null, null, null, null, null, List.of(), held);
	}

	/** One frame is enough to dequeue the next item - the clock only matters for expiry. */
	private void renderFrame()
	{
		BufferedImage canvas = new BufferedImage(800, 600, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = canvas.createGraphics();
		try
		{
			overlay.render(graphics);
		}
		finally
		{
			graphics.dispose();
		}
	}

	@Test
	public void heldItemDoesNotShowUntilReleased()
	{
		enqueue("Twisted bow", RarityTier.VERY_RARE, true);

		renderFrame();
		verify(soundManager, never()).play(RarityTier.VERY_RARE);
		assertFalse("a held item still counts as queued", overlay.isIdle());

		overlay.releaseHeld();
		renderFrame();
		verify(soundManager).play(RarityTier.VERY_RARE);
	}

	@Test
	public void audioOnlyPlaysSoundWithoutDrawing()
	{
		when(config.panelStyle()).thenReturn(PanelStyle.AUDIO_ONLY);
		enqueue("Twisted bow", RarityTier.VERY_RARE, false);

		BufferedImage canvas = new BufferedImage(800, 600, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = canvas.createGraphics();
		try
		{
			assertNull(overlay.render(graphics));
		}
		finally
		{
			graphics.dispose();
		}
		verify(soundManager).play(RarityTier.VERY_RARE);
	}

	/**
	 * The queue is FIFO, so a held item sitting at the head must not stall the ones behind it - the
	 * player would otherwise lose every unrelated unlock until they opened the chest.
	 */
	@Test
	public void heldItemDoesNotBlockLaterUnlocks()
	{
		enqueue("Twisted bow", RarityTier.VERY_RARE, true);
		enqueue("Clue scroll reward", RarityTier.COMMON, false);

		renderFrame();

		verify(soundManager).play(RarityTier.COMMON);
		verify(soundManager, never()).play(RarityTier.VERY_RARE);
	}

	/**
	 * Drains the queue by rendering past each item's expiry. overlayDisplaySeconds is stubbed to 0
	 * here so the wait is the fold/pop/fade animation only, rather than five real seconds per item.
	 */
	@Test
	public void releasedItemsShowInUnlockOrder() throws InterruptedException
	{
		enqueue("Twisted bow", RarityTier.VERY_RARE, true);
		enqueue("Kodai insignia", RarityTier.RARE, true);

		overlay.releaseHeld();

		// Three passes: dequeue the first, dequeue the second once it expires, then let the second
		// expire too so the overlay ends up genuinely idle.
		for (int i = 0; i < 3; i++)
		{
			renderFrame();
			Thread.sleep(TOTAL_ANIMATION_MILLIS);
		}
		renderFrame();

		InOrder order = inOrder(soundManager);
		order.verify(soundManager).play(RarityTier.VERY_RARE);
		order.verify(soundManager).play(RarityTier.RARE);
		assertTrue(overlay.isIdle());
	}

	/** Exactly one sound per burst when bulkUnlockSfx is on, held items included. */
	@Test
	public void releasedBurstPlaysOneSound()
	{
		enqueue("Twisted bow", RarityTier.VERY_RARE, true);
		enqueue("Kodai insignia", RarityTier.RARE, true);

		overlay.releaseHeld();
		renderFrame();

		verify(soundManager, times(1)).play(RarityTier.VERY_RARE);
		verify(soundManager, never()).play(RarityTier.RARE);
	}
}

package com.snakesteak.collectionlogpopupenhanced.overlay;

import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import net.runelite.client.ui.FontManager;
import org.junit.Test;

import static org.junit.Assert.assertTrue;

/**
 * The corner's single-line values are drawn without truncation, so an over-wide drop rate range
 * clips silently under the icon. Measured against the real font, the way KillCountLabelWidthTest
 * does for labels.
 */
public class DropRateWidthTest
{
	// CollectionLogOverlay#cornerTextMaxWidth at 100% scale: iconX - cornerPaddingX, where
	// iconX = (BASE_PANEL_WIDTH - BASE_ICON_CANVAS_SIZE) / 2 = (379 - 89) / 2.
	private static final int CORNER_TEXT_MAX_WIDTH = (379 - 89) / 2 - 16;

	// BASE_CORNER_VALUE_FONT_SIZE - the size a single-line value is drawn at.
	private static final float VALUE_FONT_SIZE = 19f;

	private static final FontMetrics METRICS;

	static
	{
		Font font = FontManager.getRunescapeBoldFont().deriveFont(VALUE_FONT_SIZE);
		Graphics2D graphics = new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB).createGraphics();
		METRICS = graphics.getFontMetrics(font);
	}

	// The widest range the shipped dataset produces (Heron, across 6 sources). It does not fit, which
	// is the whole reason the compact form exists - if this ever starts fitting, the compact path is
	// dead code rather than broken.
	@Test
	public void theWidestRealRangeDoesNotFitExact()
	{
		assertTrue("\"1/5000 - 1/1845k\" now fits - re-check whether the compact form is still needed",
			METRICS.stringWidth("1/5000 - 1/1845k") > CORNER_TEXT_MAX_WIDTH);
	}

	// Its compact rendering must fit, or the fallback buys nothing.
	@Test
	public void theCompactFormOfTheWidestRealRangeFits()
	{
		assertFits("1/5k - 1/1845k");
	}

	// The compact form only helps where a 4-digit denominator becomes one decimal of k; these are
	// the widest such ranges in the dataset.
	@Test
	public void compactFormsOfTheOtherWideRangesFit()
	{
		assertFits("1/5.8k - 1/313k");
		assertFits("1/1.5k - 1/3k");
		assertFits("1/1.2k - 1/3k");
		assertFits("1/4.5k - 1/5.4k");
	}

	// Ranges that already fit are shown exactly, so they have to keep fitting.
	@Test
	public void typicalExactRangesStillFit()
	{
		assertFits("1/1232 - 1/3003");
		assertFits("1/1500 - 1/3000");
		assertFits("1/540 - 1/1350");
		assertFits("1/160k - 1/800k");
	}

	private static void assertFits(String text)
	{
		int width = METRICS.stringWidth(text);
		assertTrue("\"" + text + "\" measures " + width + "px, over the " + CORNER_TEXT_MAX_WIDTH
			+ "px the panel gives a corner value - it would be drawn clipped", width <= CORNER_TEXT_MAX_WIDTH);
	}
}

package com.snakesteak.collectionlogpopupenhanced.overlay;

import com.snakesteak.collectionlogpopupenhanced.rarity.RarityTier;
import java.awt.Color;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.io.InputStream;
import javax.imageio.ImageIO;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class PanelRecolorerTest
{
	/**
	 * The stock accent colour baked into each bundled asset, which is also that tier's config default.
	 */
	private static final Object[][] TIERS = {
		{RarityTier.COMMON, "Backgrounds/BackgroundPanel1.png", "Icons/IconPanel1.png", 0xFFFFFF},
		{RarityTier.UNCOMMON, "Backgrounds/BackgroundPanel2.png", "Icons/IconPanel2.png", 0x1888C9},
		{RarityTier.RARE, "Backgrounds/BackgroundPanel3.png", "Icons/IconPanel3.png", 0x8431A6},
		{RarityTier.VERY_RARE, "Backgrounds/BackgroundPanel4.png", "Icons/IconPanel4.png", 0xB19F3B},
		{RarityTier.PET, "Backgrounds/BackgroundPanelPet.png", "Icons/IconPanelPet.png", 0xDC2367},
	};

	private static BufferedImage load(String resource) throws IOException
	{
		try (InputStream in = PanelRecolorerTest.class.getResourceAsStream("/Colorful/" + resource))
		{
			return ImageIO.read(in);
		}
	}

	/**
	 * The accent family (border, divider) is driven directly by the tier colour, so recolouring to a
	 * tier's stock colour must reproduce the original border. The fill is now derived rather than
	 * configured, so it is deliberately not asserted here.
	 */
	@Test
	public void stockTierColourReproducesBorder() throws IOException
	{
		for (Object[] tier : TIERS)
		{
			Color tierColour = new Color((Integer) tier[3]);
			BufferedImage src = load((String) tier[1]);
			BufferedImage out = PanelRecolorer.recolor(src, (RarityTier) tier[0], tierColour,
				PanelRecolorer.deriveBackground(tierColour, 30));

			// x=190 is clear of the rounded corners; y=2 sits on the top border stripe.
			int expected = src.getRGB(190, 2);
			assertChannelsWithinOne((String) tier[1], 190, 2, expected, out.getRGB(190, 2));
		}
	}

	/** The derived background must stay clearly darker than the tier colour it came from. */
	@Test
	public void derivedBackgroundIsDarkerThanTierColour()
	{
		for (Object[] tier : TIERS)
		{
			Color tierColour = new Color((Integer) tier[3]);
			Color background = PanelRecolorer.deriveBackground(tierColour, 30);

			float[] tierHsb = Color.RGBtoHSB(tierColour.getRed(), tierColour.getGreen(), tierColour.getBlue(), null);
			float[] bgHsb = Color.RGBtoHSB(background.getRed(), background.getGreen(), background.getBlue(), null);

			assertTrue("background should be darker for " + tier[0], bgHsb[2] < tierHsb[2]);
			if (tierHsb[1] > 0.06f)
			{
				assertEquals("hue should be preserved for " + tier[0], tierHsb[0], bgHsb[0], 0.02f);
			}
		}
	}

	/** A higher darkness percentage must produce a brighter background, monotonically. */
	@Test
	public void darknessSliderIsMonotonic()
	{
		Color tierColour = new Color(0x8431A6);
		float previous = -1f;
		for (int darkness = 10; darkness <= 60; darkness += 10)
		{
			Color background = PanelRecolorer.deriveBackground(tierColour, darkness);
			float brightness = Color.RGBtoHSB(background.getRed(), background.getGreen(), background.getBlue(), null)[2];
			assertTrue("brightness should increase with darkness%", brightness > previous);
			previous = brightness;
		}
	}

	/** Geometry and alpha must survive untouched - the icon frame designs are carried by both. */
	@Test
	public void recolorPreservesDimensionsAndAlpha() throws IOException
	{
		for (Object[] tier : TIERS)
		{
			for (int asset = 1; asset <= 2; asset++)
			{
				BufferedImage src = load((String) tier[asset]);
				BufferedImage out = PanelRecolorer.recolor(src, (RarityTier) tier[0], Color.GREEN, Color.BLUE);

				assertEquals("width", src.getWidth(), out.getWidth());
				assertEquals("height", src.getHeight(), out.getHeight());

				for (int y = 0; y < src.getHeight(); y++)
				{
					for (int x = 0; x < src.getWidth(); x++)
					{
						assertEquals("alpha at " + x + "," + y,
							(src.getRGB(x, y) >>> 24) & 0xFF,
							(out.getRGB(x, y) >>> 24) & 0xFF);
					}
				}
			}
		}
	}

	/**
	 * COMMON's accent is pure white (saturation 0), which would divide by ~zero if the saturation
	 * ratio were applied blindly. Recolouring it must still produce the requested hue.
	 */
	@Test
	public void whiteAccentTierRecoloursWithoutArtifacts() throws IOException
	{
		BufferedImage src = load("Backgrounds/BackgroundPanel1.png");
		BufferedImage out = PanelRecolorer.recolor(src, RarityTier.COMMON, new Color(0x1FA84A), new Color(0x0E2E1A));

		// x=2,y=2 sits on the border stripe, which is white in the source art.
		float[] hsb = Color.RGBtoHSB((out.getRGB(2, 2) >> 16) & 0xFF, (out.getRGB(2, 2) >> 8) & 0xFF, out.getRGB(2, 2) & 0xFF, null);
		assertTrue("white accent should take the target saturation, was " + hsb[1], hsb[1] > 0.5f);
		assertEquals("hue should match the requested border colour", 0.371f, hsb[0], 0.02f);
	}

	/** The black outline defines each icon frame's silhouette and must never be recoloured. */
	@Test
	public void blackOutlineIsPreserved() throws IOException
	{
		BufferedImage src = load("Icons/IconPanelPet.png");
		BufferedImage out = PanelRecolorer.recolor(src, RarityTier.PET, Color.ORANGE, Color.CYAN);

		for (int y = 0; y < src.getHeight(); y++)
		{
			for (int x = 0; x < src.getWidth(); x++)
			{
				int p = src.getRGB(x, y);
				if (((p >>> 24) & 0xFF) < 250)
				{
					continue;
				}
				float[] hsb = Color.RGBtoHSB((p >> 16) & 0xFF, (p >> 8) & 0xFF, p & 0xFF, null);
				if (hsb[1] < 0.06f)
				{
					assertEquals("structural pixel at " + x + "," + y, p, out.getRGB(x, y));
				}
			}
		}
	}

	/**
	 * The overlay strips alpha before recolouring (see CollectionLogOverlay#opaque), so a translucent
	 * border must produce the same pixels as its opaque equivalent - the recolorer takes its alpha
	 * from the source art, never from the requested colour.
	 */
	@Test
	public void requestedColourAlphaDoesNotAffectOutput() throws IOException
	{
		BufferedImage src = load("Backgrounds/BackgroundPanel3.png");
		Color opaque = new Color(0x8431A6);
		Color translucent = new Color(0x84, 0x31, 0xA6, 0x40);

		BufferedImage fromOpaque = PanelRecolorer.recolor(src, RarityTier.RARE, opaque,
			PanelRecolorer.deriveBackground(opaque, 30));
		BufferedImage fromTranslucent = PanelRecolorer.recolor(src, RarityTier.RARE, translucent,
			PanelRecolorer.deriveBackground(translucent, 30));

		for (int y = 0; y < src.getHeight(); y++)
		{
			for (int x = 0; x < src.getWidth(); x++)
			{
				assertEquals("pixel at " + x + "," + y,
					fromOpaque.getRGB(x, y), fromTranslucent.getRGB(x, y));
			}
		}
	}

	private static void assertChannelsWithinOne(String name, int x, int y, int expected, int actual)
	{
		for (int shift : new int[]{24, 16, 8, 0})
		{
			int e = (expected >>> shift) & 0xFF;
			int a = (actual >>> shift) & 0xFF;
			assertTrue(name + " channel@" + shift + " at " + x + "," + y + " expected " + e + " but was " + a,
				Math.abs(e - a) <= 1);
		}
	}
}

package com.snakesteak.collectionlogpopupenhanced.overlay;

import com.snakesteak.collectionlogpopupenhanced.CollectionLogPopupEnhancedConfig;
import com.snakesteak.collectionlogpopupenhanced.rarity.PreviewTier;
import com.snakesteak.collectionlogpopupenhanced.sound.SoundManager;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.image.BufferedImage;
import net.runelite.api.Client;
import net.runelite.client.game.ItemManager;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/** Horizontal drift of a few px isn't obvious in the drawn result, so assert the location directly. */
public class CollectionLogOverlayCenteringTest
{
	// BASE_PANEL_WIDTH at the 100% scale stubbed below.
	private static final int PANEL_WIDTH = 379;

	private Client client;
	private CollectionLogOverlay overlay;

	@Before
	public void before()
	{
		client = mock(Client.class);
		ItemManager itemManager = mock(ItemManager.class);
		CollectionLogPopupEnhancedConfig config = mock(CollectionLogPopupEnhancedConfig.class);
		SoundManager soundManager = mock(SoundManager.class);

		when(config.overlayScalePercent()).thenReturn(100);
		when(config.backgroundDarkness()).thenReturn(50);
		when(config.panelStyle()).thenReturn(PanelStyle.COLORFUL);
		when(config.previewTier()).thenReturn(PreviewTier.NONE);
		when(config.textRenderMode()).thenReturn(TextRenderMode.SMOOTH);
		when(config.colourCommonTier()).thenReturn(Color.WHITE);
		when(config.colourUncommonTier()).thenReturn(Color.GREEN);
		when(config.colourRareTier()).thenReturn(Color.BLUE);
		when(config.colourVeryRareTier()).thenReturn(Color.MAGENTA);
		when(config.colourPetTier()).thenReturn(Color.YELLOW);

		overlay = new CollectionLogOverlay(client, itemManager, config, soundManager);
	}

	private void stubViewport(int canvasWidth, int xOffset, int width)
	{
		when(client.getRealDimensions()).thenReturn(new Dimension(canvasWidth, 720));
		when(client.getViewportXOffset()).thenReturn(xOffset);
		when(client.getViewportWidth()).thenReturn(width);
	}

	/** The location is set before the no-item early return, so an idle frame is enough. */
	private Point renderAndReadLocation()
	{
		BufferedImage canvas = new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = canvas.createGraphics();
		try
		{
			overlay.render(graphics);
		}
		finally
		{
			graphics.dispose();
		}
		return overlay.getPreferredLocation();
	}

	private void assertCenteredOn(int expectedCenterX)
	{
		assertEquals(expectedCenterX - PANEL_WIDTH / 2, renderAndReadLocation().x);
	}

	/** Sidebar closed: the viewport fills the canvas, so the two centers coincide. */
	@Test
	public void centersOnTheViewportInPlainResizable()
	{
		stubViewport(1280, 0, 1280);
		assertCenteredOn(640);
	}

	/** Fixed/classic offsets the viewport left of the sidebar inside a wider canvas. */
	@Test
	public void centersOnTheViewportInFixedMode()
	{
		stubViewport(1280, 108, 512);
		assertCenteredOn(364);
	}

	/** Fixed Resizable Hybrid narrows the viewport by 249px while isResized() still reads true. */
	@Test
	public void centersOnTheViewportUnderAHybridStyleNarrowedViewport()
	{
		stubViewport(1280, 0, 1280 - 249);
		assertCenteredOn((1280 - 249) / 2);
	}

	/** A 0-width viewport falls back to the canvas center rather than pinning the panel left. */
	@Test
	public void fallsBackToTheCanvasCenterWhenTheViewportIsDegenerate()
	{
		stubViewport(1280, 0, 0);
		assertCenteredOn(640);
	}

	/** y is TOP_MARGIN regardless of which branch ran. */
	@Test
	public void alwaysSitsAtTheTopMargin()
	{
		stubViewport(1280, 0, 1280);
		assertEquals(2, renderAndReadLocation().y);
	}
}

package com.snakesteak.collectionlogpopupenhanced.overlay;

import com.snakesteak.collectionlogpopupenhanced.CollectionLogPopupEnhancedConfig;
import com.snakesteak.collectionlogpopupenhanced.killcount.KillCountKind;
import com.snakesteak.collectionlogpopupenhanced.rarity.PreviewTier;
import com.snakesteak.collectionlogpopupenhanced.rarity.RarityTier;
import com.snakesteak.collectionlogpopupenhanced.sound.SoundManager;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.List;
import net.runelite.api.Client;
import net.runelite.client.game.ItemManager;
import net.runelite.client.util.AsyncBufferedImage;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertNotNull;
import static org.mockito.ArgumentMatchers.anyInt;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * Covers the icon path's tolerance of items the client can't hand back a sprite for. The panel is
 * rendered for real against an offscreen image, so a null dereference in the draw path surfaces here
 * as a failing test rather than as an "Error during overlay rendering" line in a user's log.
 */
public class CollectionLogOverlayIconTest
{
	// A real id whose sprite came back null in practice, taking the panel's rendering down with it.
	private static final int ITEM_ID = 29265;

	// The icon only starts drawing once the fold-open animation has played out (FOLD_MILLIS), so a
	// null sprite goes unnoticed before then - every assertion here has to render past it.
	private static final long PAST_FOLD_MILLIS = 700;

	private ItemManager itemManager;
	private CollectionLogOverlay overlay;

	@Before
	public void before()
	{
		Client client = mock(Client.class);
		itemManager = mock(ItemManager.class);
		CollectionLogPopupEnhancedConfig config = mock(CollectionLogPopupEnhancedConfig.class);
		SoundManager soundManager = mock(SoundManager.class);

		// Unstubbed these return 0, sending render() down its degenerate-viewport fallback.
		when(client.getViewportXOffset()).thenReturn(4);
		when(client.getViewportWidth()).thenReturn(1272);
		when(client.getRealDimensions()).thenReturn(new Dimension(1280, 720));

		when(config.overlayScalePercent()).thenReturn(100);
		when(config.overlayDisplaySeconds()).thenReturn(5);
		when(config.backgroundDarkness()).thenReturn(50);
		when(config.panelStyle()).thenReturn(PanelStyle.COLORFUL);
		when(config.previewTier()).thenReturn(PreviewTier.NONE);
		when(config.textRenderMode()).thenReturn(TextRenderMode.SMOOTH);
		when(config.leftPanelStat()).thenReturn(LeftPanelStat.KILL_COUNT);
		when(config.rightPanelStat()).thenReturn(RightPanelStat.DROP_RATE);
		when(config.showProgressBar()).thenReturn(true);
		when(config.bulkUnlockSfx()).thenReturn(false);
		when(config.colourStatLabel()).thenReturn(Color.WHITE);
		when(config.colourStatValue()).thenReturn(Color.WHITE);
		when(config.colourCaption()).thenReturn(Color.WHITE);
		when(config.colourCommonTier()).thenReturn(Color.WHITE);
		when(config.colourUncommonTier()).thenReturn(Color.GREEN);
		when(config.colourRareTier()).thenReturn(Color.BLUE);
		when(config.colourVeryRareTier()).thenReturn(Color.MAGENTA);
		when(config.colourPetTier()).thenReturn(Color.YELLOW);

		overlay = new CollectionLogOverlay(client, itemManager, config, soundManager);
	}

	private void renderPastFold() throws InterruptedException
	{
		BufferedImage canvas = new BufferedImage(800, 600, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = canvas.createGraphics();
		try
		{
			// First frame starts the notification's clock; the icon is still folded shut here.
			assertNotNull(overlay.render(graphics));
			Thread.sleep(PAST_FOLD_MILLIS);
			// Second frame lands inside the icon's pop window, which is what draws the sprite.
			assertNotNull(overlay.render(graphics));
		}
		finally
		{
			graphics.dispose();
		}
	}

	@Test
	public void rendersWhenTheItemHasNoSprite() throws InterruptedException
	{
		// The client returns null for an id it has no sprite for, even when the id itself is valid.
		when(itemManager.getImage(anyInt())).thenReturn(null);

		overlay.enqueue("Guild hunter top", ITEM_ID, RarityTier.COMMON, 480, true, 15.4,
			null, null, null, null, List.of());

		renderPastFold();
	}

	@Test
	public void rendersWhenTheItemHasASprite() throws InterruptedException
	{
		AsyncBufferedImage sprite = mock(AsyncBufferedImage.class);
		// Item sprites are a fixed 36x32; the icon path scales from these, so a 0x0 mock would
		// divide by zero and mask what this test is actually checking.
		when(sprite.getWidth()).thenReturn(36);
		when(sprite.getHeight()).thenReturn(32);
		when(itemManager.getImage(anyInt())).thenReturn(sprite);

		overlay.enqueue("Guild hunter top", ITEM_ID, RarityTier.COMMON, 480, true, 15.4,
			312, KillCountKind.RUMOURS, "Hunter Guild", null, List.of());

		renderPastFold();
	}

	@Test
	public void rendersWhenTheItemIdItselfIsUnresolved() throws InterruptedException
	{
		// The pre-existing sentinel case: a negative id short-circuits before the sprite lookup.
		overlay.enqueue("Some unknown item", -1, RarityTier.COMMON, 0, false, null,
			null, null, null, null, List.of());

		renderPastFold();
	}
}

package com.snakesteak.collectionlogpopupenhanced.killcount;

import static org.junit.Assert.assertEquals;
import org.junit.Test;

public class KillCountKindTest
{
	// The tracker reconstructs the source from the casket message's difficulty word, which arrives in
	// the game's own casing - lowercase in practice. Each tier is asserted in that form.
	@Test
	public void namesEachClueCasketTier()
	{
		assertEquals("Beginner caskets: ", KillCountKind.COMPLETIONS.labelFor("beginner Treasure Trails"));
		assertEquals("Easy caskets: ", KillCountKind.COMPLETIONS.labelFor("easy Treasure Trails"));
		assertEquals("Medium caskets: ", KillCountKind.COMPLETIONS.labelFor("medium Treasure Trails"));
		assertEquals("Hard caskets: ", KillCountKind.COMPLETIONS.labelFor("hard Treasure Trails"));
		assertEquals("Elite caskets: ", KillCountKind.COMPLETIONS.labelFor("elite Treasure Trails"));
		assertEquals("Master caskets: ", KillCountKind.COMPLETIONS.labelFor("master Treasure Trails"));
	}

	@Test
	public void namesEachRaidAndItsDifficultyModes()
	{
		assertEquals("CoX completions: ", KillCountKind.COMPLETIONS.labelFor("Chambers of Xeric"));
		assertEquals("CoX CM: ", KillCountKind.COMPLETIONS.labelFor("Chambers of Xeric Challenge Mode"));
		assertEquals("ToB completions: ", KillCountKind.COMPLETIONS.labelFor("Theatre of Blood"));
		assertEquals("ToB Entry: ", KillCountKind.COMPLETIONS.labelFor("Theatre of Blood: Entry Mode"));
		assertEquals("ToB Hard Mode: ", KillCountKind.COMPLETIONS.labelFor("Theatre of Blood: Hard Mode"));
		assertEquals("ToA completions: ", KillCountKind.COMPLETIONS.labelFor("Tombs of Amascut"));
		assertEquals("ToA Entry: ", KillCountKind.COMPLETIONS.labelFor("Tombs of Amascut: Entry Mode"));
		assertEquals("ToA Expert: ", KillCountKind.COMPLETIONS.labelFor("Tombs of Amascut: Expert Mode"));
	}

	@Test
	public void fallsBackToTheGenericLabelForAnUnnamedSource()
	{
		// The Gauntlet is deliberately not in the table - see AGENTS.md.
		assertEquals("Completions: ", KillCountKind.COMPLETIONS.labelFor("Gauntlet"));
		assertEquals("Completions: ", KillCountKind.COMPLETIONS.labelFor("Corrupted Gauntlet"));
	}

	// An unlock with no correlated kill behind it renders no kill count stat at all, but the label
	// must still be well-defined for a caller that asks anyway.
	@Test
	public void fallsBackToTheGenericLabelWithNoSource()
	{
		assertEquals("Kills: ", KillCountKind.KILLS.labelFor(null));
		assertEquals("Completions: ", KillCountKind.COMPLETIONS.labelFor(null));
	}

	// Only COMPLETIONS is qualified, so a source that happens to key into a table can't re-label a
	// kind that already says what it counts.
	@Test
	public void doesNotQualifyOtherKinds()
	{
		assertEquals("Kills: ", KillCountKind.KILLS.labelFor("hard Treasure Trails"));
		assertEquals("Chests: ", KillCountKind.CHESTS.labelFor("Tombs of Amascut: Expert Mode"));
		assertEquals("Rumours: ", KillCountKind.RUMOURS.labelFor("Hunter Guild"));
		assertEquals("Delves: ", KillCountKind.DELVES.labelFor("Doom of Mokhaiotl"));
	}

	// A tier the table doesn't know renders the generic label rather than a raw, unbudgeted one.
	@Test
	public void doesNotQualifyAnUnknownClueTier()
	{
		assertEquals("Completions: ", KillCountKind.COMPLETIONS.labelFor("legendary Treasure Trails"));
	}
}

